INSERT INTO public.courses VALUES
	('12cab453-7e2d-4d63-a44e-6b1bf23c3c19', 'Tally Prime with GST', 'Accounting', 'Complete Tally training with GST, TDS, Payroll & real business case studies.', 'Industry-grade Tally Prime course covering accounting fundamentals, inventory, GST returns, TDS, payroll, and bank reconciliation. Includes real-company practice files.', '[]', '2 Months', '₹6,999', 'Job Oriented', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800&q=80', true, true, 2, '2026-04-26 19:11:04.840927+00', '2026-04-26 19:23:42.449278+00', NULL, NULL, 'enroll_button'),
	('2c4ac671-aab1-455e-8c0d-5fe71cf96468', 'Busy Accounting Software', 'Accounting', 'Master Busy software for accounting, inventory & GST compliance.', 'Comprehensive Busy training for retail, wholesale & manufacturing businesses. Covers multi-branch accounting, stock management & GST filing.', '[]', '1.5 Months', '₹5,499', '', 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&q=80', false, true, 3, '2026-04-26 19:11:04.840927+00', '2026-04-26 19:23:42.449278+00', NULL, NULL, 'enroll_button'),
	('aedc62af-0a46-4af5-b329-10c5b531d09d', 'Python Programming', 'Programming', 'From basics to data structures, OOP & real-world projects.', 'Learn Python from scratch — variables, loops, functions, OOP, file handling, and mini-projects. Foundation for data science, AI & web development.', '[]', '3 Months', '₹9,999', 'In Demand', 'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?w=800&q=80', true, true, 4, '2026-04-26 19:11:04.840927+00', '2026-04-26 19:23:42.449278+00', NULL, NULL, 'enroll_button'),
	('eccea9bf-ad60-4f92-9777-e2f6fd11e73a', 'Digital Marketing Pro', 'Marketing', 'SEO, Google Ads, Meta Ads, Social Media & Content Marketing.', 'End-to-end digital marketing course covering SEO, SEM, social media marketing, email marketing, analytics, and freelancing strategies.', '[]', '3 Months', '₹12,999', 'High Demand', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&q=80', true, true, 5, '2026-04-26 19:11:04.840927+00', '2026-04-26 19:23:42.449278+00', NULL, NULL, 'enroll_button'),
	('f7972c6b-86f7-48a8-8d8a-7dcb9c04cb28', 'Computer Basics & MS Office', 'Foundation', 'Computer fundamentals, Word, Excel, PowerPoint & Internet.', 'Perfect starter course covering computer basics, typing, MS Office suite, and internet skills for office jobs and government exam preparation.', '[]', '2 Months', '₹3,999', 'Beginner', 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?w=800&q=80', false, true, 6, '2026-04-26 19:11:04.840927+00', '2026-04-26 19:23:42.449278+00', NULL, NULL, 'enroll_button'),
	('eac90484-d9b9-4489-b2fe-b6ba28a5e29c', 'Web Development', 'Programming', 'HTML, CSS, JavaScript, React & build live websites.', 'Frontend web development bootcamp. Build real responsive websites and a full portfolio. Includes Git/GitHub and deployment.', '[]', '4 Months', '₹14,999', '', 'https://images.unsplash.com/photo-1547658719-da2b51169166?w=800&q=80', false, true, 7, '2026-04-26 19:11:04.840927+00', '2026-04-26 19:23:42.449278+00', NULL, NULL, 'enroll_button'),
	('b4edf30e-a47a-4abf-8477-8d39968f24a4', 'Graphic Designing', 'Creative', 'Photoshop, Illustrator, Canva & design portfolio building.', 'Master industry tools — Photoshop, Illustrator & Canva. Build a freelance-ready portfolio with logos, posters, social media creatives.', '[]', '3 Months', '₹8,999', '', 'https://images.unsplash.com/photo-1626785774573-4b799315345d?w=800&q=80', false, true, 8, '2026-04-26 19:11:04.840927+00', '2026-04-26 19:23:42.449278+00', NULL, NULL, 'enroll_button'),
	('f5dd9898-9395-4e0f-8ecd-695ac30ff9dc', 'Mern Full Stack', 'Full Stack & Networking', 'REACT | NODE.JS | TAILWIND.CSS | TYPESCRIPT', '', '[]', '6 Months', '24000', '', 'https://images.unsplash.com/photo-1646122580600-4d6cffc926fe?q=80&w=1257&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D', true, true, 9, '2026-04-26 21:15:56.193471+00', '2026-04-26 21:18:28.709095+00', '', '', 'get the details'),
	('4f881bbb-0640-4102-bea8-1d56919e38fc', 'Artificial Intelligence Mastery', 'AI & Tech', 'Master ChatGPT, Midjourney, Prompt Engineering & build AI tools for businesses.', 'Complete AI course covering generative AI, prompt engineering, AI tools for content/video/data, chatbot building, and earning opportunities. Perfect for students, freelancers, and working professionals.', '"[FULL SYLLABUS Complete AI course covering generative AI, prompt engineering, AI tools for content/video/data, chatbot building, and earning opportunities. Perfect for students, freelancers, and working professionals.Complete AI course covering generative AI, prompt engineering, AI tools for content/video/data, chatbot building, and earning opportunities. Perfect for students, freelancers, and working professionals.]"', '3 Months', '₹15,999', 'Most Popular', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=800&q=80', true, true, 1, '2026-04-26 19:11:04.840927+00', '2026-04-29 07:45:44.129828+00', NULL, NULL, 'enroll_button');
INSERT INTO public.crm_courses VALUES
	('a5a769c4-e71c-4314-ac7c-5bb133e52ce8', 'GST & Taxation', 'finance', '1.5 Months', 'offline', 7000, 0, '[]', 'GST registration, returns (GSTR-1, 3B, 9), e-invoicing, TDS, TCS, income tax basics, return filing and reconciliation. Practical training with portal demos.', NULL, NULL, NULL, NULL, NULL, 'Certificate in GST & Taxation', true, 2, 'gst-taxation', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('a15b3d1b-f260-44d2-b38e-ab26726fd45c', 'Accounting', 'finance', '3 Months', 'offline', 10000, 0, '[]', 'Manual + computerized accounting from journal entries to final accounts. Covers double entry, balance sheet, P&L, bank reconciliation and Tally integration.', NULL, NULL, NULL, NULL, NULL, 'Diploma in Accounting', true, 3, 'accounting', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('2d5d2d34-a4ba-48d6-8b02-4aea0b6351cf', 'Banking & Finance', 'finance', '2 Months', 'offline', 7500, 0, '[]', 'Banking operations, NEFT/RTGS/UPI, KYC, loan processing, financial markets basics, mutual funds and personal finance fundamentals.', NULL, NULL, NULL, NULL, NULL, 'Certificate in Banking & Finance', true, 4, 'banking-finance', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('a471a779-ff57-4743-a01e-dafae70417fe', 'Stock Market Trading', 'finance', '2 Months', 'offline', 9000, 0, '[]', 'Stock market basics, technical & fundamental analysis, intraday vs delivery, F&O introduction, demat account, charting tools and risk management.', NULL, NULL, NULL, NULL, NULL, 'Certificate in Stock Market Trading', true, 5, 'stock-market-trading', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('f8408cac-28fe-447f-b54d-a0c1e8cb80e5', 'Financial Accounting', 'finance', '3 Months', 'offline', 9500, 0, '[]', 'Advanced financial accounting: standards (Ind-AS basics), depreciation, inventory valuation, partnership accounts, company accounts and audit basics.', NULL, NULL, NULL, NULL, NULL, 'Diploma in Financial Accounting', true, 6, 'financial-accounting', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('f2ce9d48-d678-4483-8d4c-a6344df260e4', 'Insurance', 'finance', '1 Month', 'offline', 5000, 0, '[]', 'Life, health and general insurance fundamentals, IRDAI regulations, claim process, policy comparison and insurance advisor preparation.', NULL, NULL, NULL, NULL, NULL, 'Certificate in Insurance', true, 7, 'insurance', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('d7779a94-0072-46a8-bc30-b6e35705dd14', 'MS Office', 'computer', '2 Months', 'offline', 5000, 0, '[]', 'Microsoft Word, Excel, PowerPoint and Outlook with practical assignments. Covers formulas, charts, mail merge, presentations and email management.', NULL, NULL, NULL, NULL, NULL, 'Certificate in MS Office', true, 10, 'ms-office', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('0523eb5a-0c3f-45a0-b769-9e38dad4d941', 'DTP & Printing', 'computer', '2 Months', 'offline', 6000, 0, '[]', 'PageMaker, CorelDraw, Photoshop basics for designing visiting cards, brochures, flex banners and print-ready files. Includes printing process overview.', NULL, NULL, NULL, NULL, NULL, 'Certificate in DTP & Printing', true, 11, 'dtp-printing', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('197b7b21-9265-4d16-bb1f-03c2966610a9', 'Web Design', 'computer', '3 Months', 'offline', 9000, 0, '[]', 'HTML5, CSS3, JavaScript, Bootstrap and responsive design. Build live portfolio websites and learn deployment basics.', NULL, NULL, NULL, NULL, NULL, 'Diploma in Web Design', true, 12, 'web-design', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('1f21d169-e817-494d-802e-62ce1668e351', 'Python Programming', 'computer', '3 Months', 'offline', 10000, 0, '[]', 'Python fundamentals to OOP, file handling, modules, libraries (NumPy, Pandas), basic web scraping and intro to automation/AI scripts.', NULL, NULL, NULL, NULL, NULL, 'Diploma in Python Programming', true, 13, 'python-programming', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('64b3e2af-a927-4738-a0eb-ee32a5313ed2', 'Java Programming', 'computer', '3 Months', 'offline', 10000, 0, '[]', 'Core Java: OOP, collections, exception handling, file I/O, JDBC and intro to Spring Boot. Build small console and web applications.', NULL, NULL, NULL, NULL, NULL, 'Diploma in Java Programming', true, 14, 'java-programming', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('d55212d6-80d4-4a53-ab63-d45528624b19', 'Graphic Design', 'computer', '3 Months', 'offline', 9500, 0, '[]', 'Photoshop, Illustrator, CorelDraw and Canva. Logo design, social media creatives, posters, branding kits and portfolio building.', NULL, NULL, NULL, NULL, NULL, 'Diploma in Graphic Design', true, 15, 'graphic-design', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('494140f3-0495-49a3-a5fb-c6b499ee5d3e', 'AutoCAD', 'computer', '2 Months', 'offline', 9000, 0, '[]', '2D & 3D drafting in AutoCAD, floor plans, elevations, sections, dimensioning, layers and printing. Practical drawings of real projects.', NULL, NULL, NULL, NULL, NULL, 'Certificate in AutoCAD', true, 16, 'autocad', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('2fa75688-b581-410d-a593-f90f79cf8107', 'Cyber Security', 'computer', '3 Months', 'offline', 12000, 0, '[]', 'Networking basics, ethical hacking introduction, Linux fundamentals, web security (OWASP Top 10), Kali tools overview and safe browsing.', NULL, NULL, NULL, NULL, NULL, 'Diploma in Cyber Security', true, 17, 'cyber-security', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('310538ce-7ed0-4fb8-b8a4-27ed9be35a1e', 'Digital Marketing', 'computer', '3 Months', 'offline', 11000, 0, '[]', 'SEO, SEM, social media marketing, Google Ads, Facebook/Instagram Ads, email marketing, content marketing and Google Analytics.', NULL, NULL, NULL, NULL, NULL, 'Diploma in Digital Marketing', true, 18, 'digital-marketing', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
	('b6d38eb9-402e-4c7c-ba39-3263f4dc26a2', 'Video Editing', 'computer', '2 Months', 'offline', 8500, 0, '[]', 'Adobe Premiere Pro & After Effects basics. Cuts, transitions, color grading, motion graphics, YouTube and reels editing workflows.', NULL, NULL, NULL, NULL, NULL, 'Certificate in Video Editing', true, 19, 'video-editing', NULL, NULL, NULL, NULL, '2026-04-28 21:16:54.324993+00', '2026-04-28 21:16:54.324993+00'),
